"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { MessageSquare, Plus } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * ChatThreadsPanel — the nested chat sidebar: a glass rail that slides open
 * beside the transcript and keeps track of conversation threads.
 *
 * Presentational and framework-free: threads, the active id, and the
 * select/new callbacks are injected — no router, no data fetching. The host
 * owns the `open` state (toolbar toggle) and the width animation lives here
 * so every consumer gets the same spring.
 */

export type ChatThread = {
  chatId: string;
  title: string;
  /** ISO string (JSON-serialized Date) or epoch ms. */
  updatedAt: string | number;
};

type Props = {
  open: boolean;
  threads: ChatThread[];
  activeId: string;
  onSelect: (chatId: string) => void;
  onNew: () => void;
  className?: string;
};

const PANEL_WIDTH = 240;

export function ChatThreadsPanel({ open, threads, activeId, onSelect, onNew, className }: Props) {
  const reduced = useReducedMotion();

  // Closed = unmounted. That keeps the animation on transform/opacity only
  // (animating width forces the browser to re-lay-out the page every frame)
  // and means a closed panel has no focusable buttons lingering in the tab
  // order behind an aria-hidden wall. The column width snaps once on
  // mount/unmount; the slide + fade carries the motion.
  return (
    <AnimatePresence initial={false}>
      {open && (
        <motion.aside
          initial={{ x: -24, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          exit={{ x: -24, opacity: 0 }}
          transition={reduced ? { duration: 0 } : { type: "spring", stiffness: 260, damping: 28 }}
          className={cn("shrink-0", className)}
          style={{ width: PANEL_WIDTH }}
        >
          <div className="mt-liquid-css flex h-full flex-col rounded-bubble-md p-2">
            <div className="flex items-center justify-between px-2 pb-2 pt-1">
              <span className="mt-type-eyebrow text-muted-foreground">Threads</span>
              <button
                type="button"
                onClick={onNew}
                className="flex size-7 items-center justify-center rounded-bubble-sm bg-[var(--color-gold-soft)] text-[var(--color-gold-fg)] transition-colors hover:bg-[var(--color-gold)] hover:text-[var(--color-gold-foreground)]"
                aria-label="New thread"
              >
                <Plus className="size-4" />
              </button>
            </div>

            <div className="min-h-0 flex-1 space-y-1 overflow-y-auto">
              {threads.length === 0 && (
                <p className="px-2 py-3 text-xs text-muted-foreground">
                  No threads yet — say something.
                </p>
              )}
              {threads.map((t) => {
                const active = t.chatId === activeId;
                return (
                  <button
                    key={t.chatId}
                    type="button"
                    onClick={() => onSelect(t.chatId)}
                    className={cn(
                      "flex w-full flex-col gap-0.5 rounded-bubble-sm px-2.5 py-2 text-left transition-colors",
                      active
                        ? "bg-[var(--color-sidebar-accent)] text-foreground"
                        : "text-muted-foreground hover:bg-accent hover:text-foreground",
                    )}
                    aria-current={active ? "true" : undefined}
                  >
                    <span
                      className={cn("flex items-center gap-1.5 text-sm", active && "font-medium")}
                    >
                      <MessageSquare className="size-3.5 shrink-0 opacity-60" />
                      <span className="truncate">{t.title}</span>
                    </span>
                    <span className="pl-5 text-2xs text-muted-foreground">
                      {relativeTime(t.updatedAt)}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </motion.aside>
      )}
    </AnimatePresence>
  );
}

/** "now" / "5m" / "3h" / "2d" / short date — list-row scale, no library. */
function relativeTime(value: string | number): string {
  const then = typeof value === "number" ? value : Date.parse(value);
  if (!Number.isFinite(then)) return "";
  const s = Math.max(0, (Date.now() - then) / 1000);
  if (s < 60) return "now";
  if (s < 3600) return `${Math.floor(s / 60)}m`;
  if (s < 86400) return `${Math.floor(s / 3600)}h`;
  if (s < 7 * 86400) return `${Math.floor(s / 86400)}d`;
  return new Date(then).toLocaleDateString(undefined, { month: "short", day: "numeric" });
}
